CREATE SCHEMA IF NOT EXISTS dbo;
CREATE TABLE IF NOT EXISTS dbo.Usuario(usuario_id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,nombre NVARCHAR(120) NOT NULL,correo NVARCHAR(254) UNIQUE NOT NULL,password_hash VARCHAR(255) NOT NULL,habilitado BIT DEFAULT 1,creado_en TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS dbo.Orientador(usuario_id BIGINT PRIMARY KEY REFERENCES dbo.Usuario,descripcion NVARCHAR(1000) DEFAULT '',whatsapp VARCHAR(15),publicar BIT DEFAULT 0,actualizado_en TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS dbo.Especialidad(especialidad_id INT PRIMARY KEY,nombre NVARCHAR(80));
CREATE TABLE IF NOT EXISTS dbo.OrientadorEspecialidad(usuario_id BIGINT REFERENCES dbo.Orientador,especialidad_id INT REFERENCES dbo.Especialidad,PRIMARY KEY(usuario_id,especialidad_id));
CREATE TABLE IF NOT EXISTS dbo.Suscripcion(suscripcion_id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,usuario_id BIGINT REFERENCES dbo.Orientador,inicio TIMESTAMP WITH TIME ZONE,fin TIMESTAMP WITH TIME ZONE,es_simulada BIT DEFAULT 1);
MERGE INTO dbo.Especialidad KEY(especialidad_id) VALUES(1,'Java');
